public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        try {
            return doSearch(objectApiName, fields, filters, orderByField, maxRows);
        } catch (SearchException e) {
            throw e;
        } catch (Exception e) {
            throw new SearchException('Search failed: ' + e.getMessage());
        }
    }

    private static List<SObject> doSearch(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object name is required.');
        }
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200.');
        }
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field is required.');
        }

        Schema.SObjectType sot = Schema.getGlobalDescribe().get(objectApiName.trim().toLowerCase());
        if (sot == null) {
            throw new SearchException('Unknown object: ' + objectApiName);
        }
        Schema.DescribeSObjectResult objDescribe = sot.getDescribe();
        if (!objDescribe.isAccessible()) {
            throw new SearchException('You do not have access to object ' + objDescribe.getName());
        }
        Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();

        // Select list (deduplicated, canonical names from describe)
        List<String> selectFields = new List<String>{ 'Id' };
        Set<String> seen = new Set<String>{ 'id' };
        for (String f : fields) {
            Schema.DescribeFieldResult d = describeField(fieldMap, f, objDescribe.getName());
            if (!d.isAccessible()) {
                throw new SearchException('You do not have access to field ' + d.getName());
            }
            if (seen.add(d.getName().toLowerCase())) {
                selectFields.add(d.getName());
            }
        }

        // WHERE clause with bind variables
        List<String> conditions = new List<String>();
        Map<String, Object> binds = new Map<String, Object>();
        if (filters != null) {
            Integer i = 0;
            for (String key : filters.keySet()) {
                Schema.DescribeFieldResult d = describeField(fieldMap, key, objDescribe.getName());
                if (!d.isAccessible()) {
                    throw new SearchException('You do not have access to field ' + d.getName());
                }
                if (!d.isFilterable()) {
                    throw new SearchException('Field cannot be filtered: ' + d.getName());
                }
                String bindName = 'f' + i;
                conditions.add(d.getName() + ' = :' + bindName);
                binds.put(bindName, filters.get(key));
                i++;
            }
        }

        String orderClause = '';
        if (!String.isBlank(orderByField)) {
            Schema.DescribeFieldResult d = describeField(fieldMap, orderByField, objDescribe.getName());
            if (!d.isAccessible()) {
                throw new SearchException('You do not have access to field ' + d.getName());
            }
            if (!d.isSortable()) {
                throw new SearchException('Field cannot be sorted: ' + d.getName());
            }
            orderClause = ' ORDER BY ' + d.getName() + ' ASC';
        }

        String soql = 'SELECT ' + String.join(selectFields, ', ') + ' FROM ' + objDescribe.getName();
        if (!conditions.isEmpty()) {
            soql += ' WHERE ' + String.join(conditions, ' AND ');
        }
        soql += orderClause + ' LIMIT ' + maxRows;

        return Database.queryWithBinds(soql, binds, AccessLevel.USER_MODE);
    }

    private static Schema.DescribeFieldResult describeField(
        Map<String, Schema.SObjectField> fieldMap, String name, String objName
    ) {
        if (String.isBlank(name)) {
            throw new SearchException('Blank field name.');
        }
        Schema.SObjectField f = fieldMap.get(name.trim().toLowerCase());
        if (f == null) {
            throw new SearchException('Unknown field ' + name + ' on ' + objName);
        }
        return f.getDescribe();
    }
}
```

Design notes:

- The class is `with sharing` so the running user's sharing rules apply. The query uses `WITH USER_MODE` so field and object security are enforced as well.
- Emails are trimmed and lowercased to build the lookup keys. SOQL string comparison on `Email` is case-insensitive, so the query receives the trimmed values and a single `IN` query covers the whole batch.
- The query is ordered by `CreatedDate ASC, Id ASC`. The first contact seen for each lowercase email is kept, which gives the earliest created contact, with `Id` as a deterministic tie-breaker.
- Duplicate requests with the same email are handled by the map lookup, and the results list keeps the request order.
- If no valid emails remain, no query runs.
- Null requests and null lists are handled defensively.
- Trimming uses `String.trim()`, which removes leading and trailing whitespace.

