```apex
public with sharing class ContactLookupAction {

    public class Request {
        @InvocableVariable(label='Email' description='Email address to search for' required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact Id' description='Id of the earliest created matching contact')
        public Id contactId;

        @InvocableVariable(label='Found' description='True if a contact was found')
        public Boolean found;
    }

    @InvocableMethod(
        label='Find Contact by Email'
        description='Finds the earliest created contact for each email address'
    )
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        // Normalize emails (one entry per request, null if blank)
        List<String> normalized = new List<String>();
        Set<String> queryEmails = new Set<String>();
        for (Request req : requests) {
            String key = null;
            if (req != null && req.email != null) {
                String trimmed = req.email.trim();
                if (String.isNotBlank(trimmed)) {
                    key = trimmed.toLowerCase();
                    queryEmails.add(trimmed);
                }
            }
            normalized.add(key);
        }

        // Earliest created contact per lowercase email
        Map<String, Id> contactByEmail = new Map<String, Id>();
        if (!queryEmails.isEmpty()) {
            for (Contact c : [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :queryEmails
                WITH USER_MODE
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                if (c.Email == null) {
                    continue;
                }
                String key = c.Email.trim().toLowerCase();
                if (!contactByEmail.containsKey(key)) {
                    contactByEmail.put(key, c.Id);
                }
            }
        }

        for (String key : normalized) {
            Result r = new Result();
            Id foundId = key == null ? null : contactByEmail.get(key);
            r.contactId = foundId;
            r.found = foundId != null;
            results.add(r);
        }
        return results;
    }
}
