public with sharing class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Request body is empty');
        }
        Object root;
        try {
            root = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Invalid JSON: ' + e.getMessage());
        }
        if (!(root instanceof Map<String, Object>)) {
            throw new PayloadException('Payload must be a JSON object');
        }
        Map<String, Object> obj = (Map<String, Object>) root;

        Order result = new Order();

        Object num = obj.get('number');
        if (!(num instanceof String) || String.isBlank((String) num)) {
            throw new PayloadException('Missing order number');
        }
        result.orderNumber = (String) num;

        Object d = obj.get('date');
        if (d != null) {
            if (!(d instanceof String) || !Pattern.matches('\\d{4}-\\d{2}-\\d{2}', (String) d)) {
                throw new PayloadException('Invalid date');
            }
            try {
                result.orderDate = Date.valueOf((String) d);
            } catch (Exception e) {
                throw new PayloadException('Invalid date');
            }
        }

        Object cur = obj.get('currency');
        if (cur != null) {
            if (!(cur instanceof String)) {
                throw new PayloadException('Invalid currency');
            }
            result.currencyCode = (String) cur;
        }

        Object cust = obj.get('customer');
        if (cust instanceof Map<String, Object>) {
            Object email = ((Map<String, Object>) cust).get('email');
            if (email instanceof String) {
                result.customerEmail = (String) email;
            }
        }

        result.lines = new List<Line>();
        result.total = 0;
        Object rawLines = obj.get('lines');
        if (rawLines != null) {
            if (!(rawLines instanceof List<Object>)) {
                throw new PayloadException('lines must be an array');
            }
            for (Object item : (List<Object>) rawLines) {
                if (!(item instanceof Map<String, Object>)) {
                    throw new PayloadException('Each line must be an object');
                }
                Line l = parseLine((Map<String, Object>) item);
                result.lines.add(l);
                result.total += l.lineTotal;
            }
        }
        return result;
    }

    private static Line parseLine(Map<String, Object> m) {
        Line l = new Line();

        Object sku = m.get('sku');
        if (!(sku instanceof String) || String.isBlank((String) sku)) {
            throw new PayloadException('Line is missing sku');
        }
        l.sku = (String) sku;

        Decimal q = toDecimal(m.get('quantity'), 'quantity');
        if (q == null || q <= 0 || q != q.setScale(0) || q > 2147483647) {
            throw new PayloadException('Invalid quantity for ' + l.sku);
        }
        l.quantity = q.intValue();

        Decimal price = toDecimal(m.get('unitPrice'), 'unitPrice');
        if (price == null || price < 0) {
            throw new PayloadException('Invalid unitPrice for ' + l.sku);
        }
        l.unitPrice = price;

        Decimal disc = toDecimal(m.get('discount'), 'discount');
        if (disc == null) {
            disc = 0;
        }
        if (disc < 0 || disc > 1) {
            throw new PayloadException('Invalid discount for ' + l.sku);
        }
        l.discount = disc;

        l.lineTotal = (q * price * (1 - disc)).setScale(2, RoundingMode.HALF_UP);
        return l;
    }

    // Returns null when value is null; throws when not a number.
    private static Decimal toDecimal(Object o, String field) {
        if (o == null) {
            return null;
        }
        if (o instanceof Integer || o instanceof Long || o instanceof Decimal || o instanceof Double) {
            try {
                return Decimal.valueOf(Double.valueOf(String.valueOf(o))) == null
                    ? null
                    : exact(o);
            } catch (Exception e) {
                throw new PayloadException('Invalid number for ' + field);
            }
        }
        throw new PayloadException('Invalid ' + field);
    }

    private static Decimal exact(Object o) {
        String s = String.valueOf(o);
        if (s.containsIgnoreCase('e')) {
            return Decimal.valueOf(Double.valueOf(s));
        }
        return Decimal.valueOf(s);
    }

    public static String toAcknowledgement(Order order) {
        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order.orderNumber);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', order.lines == null ? 0 : order.lines.size());
        ack.put('total', order.total == null ? 0 : order.total);
        return JSON.serialize(ack);
    }
}
