@isTest
private class AddressVerificationServiceTest {

    private class Mock implements HttpCalloutMock {
        Integer statusCode;
        String responseBody;
        Integer calls = 0;
        HttpRequest captured;

        Mock(Integer statusCode, String responseBody) {
            this.statusCode = statusCode;
            this.responseBody = responseBody;
        }

        public HttpResponse respond(HttpRequest req) {
            calls++;
            captured = req;
            HttpResponse res = new HttpResponse();
            res.setStatusCode(statusCode);
            res.setHeader('Content-Type', 'application/json');
            res.setBody(responseBody);
            return res;
        }
    }

    private static Account buildAccount() {
        return new Account(
            Name = 'Test Acct',
            BillingStreet = '1 Main St',
            BillingCity = 'Springfield',
            BillingPostalCode = '12345',
            BillingCountry = 'US'
        );
    }

    private static String correctedBody() {
        return '{"status":"CORRECTED","address":{"street":"2 Oak Ave","city":"Shelbyville",'
            + '"postalCode":"54321","country":"CA"}}';
    }

    @isTest
    static void requestMatchesContract() {
        Mock m = new Mock(200, '{"status":"VERIFIED"}');
        Test.setMock(HttpCalloutMock.class, m);
        Test.startTest();
        AddressVerificationService.verify(buildAccount());
        Test.stopTest();

        System.assertEquals(1, m.calls);
        System.assertEquals('POST', m.captured.getMethod());
        System.assertEquals('callout:FB_Address_API/v2/verify', m.captured.getEndpoint());
        System.assertEquals('application/json', m.captured.getHeader('Content-Type'));
        Map<String, Object> body = (Map<String, Object>) JSON.deserializeUntyped(m.captured.getBody());
        System.assertEquals(4, body.size());
        System.assertEquals('1 Main St', body.get('street'));
        System.assertEquals('Springfield', body.get('city'));
        System.assertEquals('12345', body.get('postalCode'));
        System.assertEquals('US', body.get('country'));
    }

    @isTest
    static void verifiedLeavesAccountUntouched() {
        Mock m = new Mock(200, '{"status":"VERIFIED","address":{"street":"X","city":"Y",'
            + '"postalCode":"Z","country":"W"}}');
        Test.setMock(HttpCalloutMock.class, m);
        Account a = buildAccount();
        Test.startTest();
        AddressVerificationService.Result r = AddressVerificationService.verify(a);
        Test.stopTest();

        System.assertEquals('VERIFIED', r.status);
        System.assertEquals(false, r.changed);
        System.assertEquals('1 Main St', a.BillingStreet);
        System.assertEquals('Springfield', a.BillingCity);
        System.assertEquals('12345', a.BillingPostalCode);
        System.assertEquals('US', a.BillingCountry);
    }

    @isTest
    static void invalidLeavesAccountUntouched() {
        Mock m = new Mock(200, '{"status":"INVALID","address":{"street":"X","city":"Y",'
            + '"postalCode":"Z","country":"W"}}');
        Test.setMock(HttpCalloutMock.class, m);
        Account a = buildAccount();
        Test.startTest();
        AddressVerificationService.Result r = AddressVerificationService.verify(a);
        Test.stopTest();

        System.assertEquals('INVALID', r.status);
        System.assertEquals(false, r.changed);
        System.assertEquals('1 Main St', a.BillingStreet);
        System.assertEquals('Springfield', a.BillingCity);
        System.assertEquals('12345', a.BillingPostalCode);
        System.assertEquals('US', a.BillingCountry);
    }

    @isTest
    static void correctedOverwritesAllFields() {
        Mock m = new Mock(200, correctedBody());
        Test.setMock(HttpCalloutMock.class, m);
        Account a = buildAccount();
        Test.startTest();
        AddressVerificationService.Result r = AddressVerificationService.verify(a);
        Test.stopTest();

        System.assertEquals('CORRECTED', r.status);
        System.assertEquals(true, r.changed);
        System.assertEquals('2 Oak Ave', a.BillingStreet);
        System.assertEquals('Shelbyville', a.BillingCity);
        System.assertEquals('54321', a.BillingPostalCode);
        System.assertEquals('CA', a.BillingCountry);
        System.assertEquals(null, a.Id);
    }

    @isTest
    static void blankStreetSkipsCallout() {
        Mock m = new Mock(200, correctedBody());
        Test.setMock(HttpCalloutMock.class, m);
        Test.startTest();
        Account a1 = buildAccount();
        a1.BillingStreet = null;
        AddressVerificationService.Result r1 = AddressVerificationService.verify(a1);
        Account a2 = buildAccount();
        a2.BillingStreet = '   ';
        AddressVerificationService.Result r2 = AddressVerificationService.verify(a2);
        Account a3 = buildAccount();
        a3.BillingStreet = '';
        AddressVerificationService.Result r3 = AddressVerificationService.verify(a3);
        Test.stopTest();

        System.assertEquals(0, m.calls);
        System.assertEquals('SKIPPED', r1.status);
        System.assertEquals('SKIPPED', r2.status);
        System.assertEquals('SKIPPED', r3.status);
        System.assertEquals(false, r1.changed);
        System.assertEquals('Springfield', a1.BillingCity);
    }

    @isTest
    static void nonOkStatusThrows() {
        for (Integer code : new List<Integer>{ 500, 404, 400, 201 }) {
            Mock m = new Mock(code, correctedBody());
            Test.setMock(HttpCalloutMock.class, m);
            Account a = buildAccount();
            Boolean thrown = false;
            Test.startTest();
            try {
                AddressVerificationService.verify(a);
            } catch (AddressVerificationService.AddressVerificationException e) {
                thrown = true;
                System.assert(e.getMessage().contains(String.valueOf(code)), e.getMessage());
            }
            Test.stopTest();
            System.assert(thrown, 'Expected exception for ' + code);
            System.assertEquals('1 Main St', a.BillingStreet);
        }
    }
}
