public with sharing class PicklistService {

    public class PicklistServiceException extends Exception {}

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName)) {
            throw new PicklistServiceException('Object API name is required.');
        }
        if (String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Field API name is required.');
        }
        String objName = objectApiName.trim();
        String fldName = fieldApiName.trim();

        Schema.SObjectType sot = Schema.getGlobalDescribe().get(objName.toLowerCase());
        if (sot == null) {
            throw new PicklistServiceException('Object does not exist: ' + objName);
        }

        Map<String, Schema.SObjectField> fields = sot.getDescribe().fields.getMap();
        Schema.SObjectField sof = fields.get(fldName.toLowerCase());
        if (sof == null) {
            throw new PicklistServiceException('Field ' + fldName + ' does not exist on ' + objName);
        }

        Schema.DescribeFieldResult dfr = sof.getDescribe();
        Schema.DisplayType dt = dfr.getType();
        if (dt != Schema.DisplayType.PICKLIST && dt != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException('Field ' + fldName + ' is not a picklist or multi-select picklist.');
        }

        List<Option> result = new List<Option>();
        for (Schema.PicklistEntry pe : dfr.getPicklistValues()) {
            if (pe.isActive()) {
                result.add(new Option(pe.getValue(), pe.getLabel(), pe.isDefaultValue()));
            }
        }
        return result;
    }
}
