public with sharing class ContactPhoneCleanup {

    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> failures = new Map<Id, String>();
        if (contactIds == null || contactIds.isEmpty()) {
            return failures;
        }

        // Query once, outside the loop. Dedupe via the Map constructor.
        List<Contact> contacts = new List<Contact>();
        for (Contact c : [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :new Set<Id>(contactIds)
            AND Phone != null
            WITH USER_MODE
        ]) {
            String cleaned = c.Phone.replaceAll('[^0-9+]', '');
            // Only send records that actually change
            if (cleaned != c.Phone) {
                c.Phone = cleaned;
                contacts.add(c);
            }
        }

        if (contacts.isEmpty()) {
            return failures;
        }

        // Single DML after the loop, allowing partial success
        List<Database.SaveResult> results = Database.update(contacts, false);

        for (Integer i = 0; i < results.size(); i++) {
            Database.SaveResult sr = results[i];
            if (!sr.isSuccess()) {
                String message = sr.getErrors().isEmpty()
                    ? 'Unknown error'
                    : sr.getErrors()[0].getMessage();
                failures.put(contacts[i].Id, message);
            }
        }

        return failures;
    }
}
