public without sharing class AccountRatingService {

    private static final Decimal HOT_THRESHOLD = 100000;

    // Convenience overload for a single account.
    public static void recalculate(Id accountId) {
        if (accountId == null) {
            return;
        }
        recalculate(new Set<Id>{ accountId });
    }

    // Bulk entry point: one async call per transaction, not per record.
    public static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }
        if (System.isFuture() || System.isBatch()) {
            // Future methods cannot be invoked from future/batch context.
            applyRatings(accountIds);
        } else {
            recalculateAccounts(accountIds);
        }
    }

    @future
    public static void recalculateAccounts(Set<Id> accountIds) {
        applyRatings(accountIds);
    }

    private static void applyRatings(Set<Id> accountIds) {
        Set<Id> hotIds = new Set<Id>();
        Set<Id> openIds = new Set<Id>();

        for (AggregateResult ar : [
            SELECT AccountId acc, MAX(Amount) maxAmount
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accId = (Id) ar.get('acc');
            openIds.add(accId);
            Decimal maxAmount = (Decimal) ar.get('maxAmount');
            if (maxAmount != null && maxAmount >= HOT_THRESHOLD) {
                hotIds.add(accId);
            }
        }

        List<Account> toUpdate = new List<Account>();
        for (Account acc : [
            SELECT Id, Rating FROM Account WHERE Id IN :accountIds
        ]) {
            String newRating = hotIds.contains(acc.Id) ? 'Hot'
                : openIds.contains(acc.Id) ? 'Warm' : 'Cold';
            if (acc.Rating != newRating) {
                acc.Rating = newRating;
                toUpdate.add(acc);
            }
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
```

