public with sharing class LineItemDiscountHandler {

    public static void applyStandardDiscounts(List<OpportunityLineItem> lines) {
        List<OpportunityLineItem> targets = new List<OpportunityLineItem>();
        Set<Id> productIds = new Set<Id>();
        Set<Id> pricebookEntryIds = new Set<Id>();

        for (OpportunityLineItem line : lines) {
            if (line.Discount != null) {
                continue;
            }
            if (line.Product2Id != null) {
                productIds.add(line.Product2Id);
                targets.add(line);
            } else if (line.PricebookEntryId != null) {
                pricebookEntryIds.add(line.PricebookEntryId);
                targets.add(line);
            }
        }

        if (targets.isEmpty()) {
            return;
        }

        // Resolve products for lines that only carry a PricebookEntryId.
        Map<Id, Id> productByEntry = new Map<Id, Id>();
        if (!pricebookEntryIds.isEmpty()) {
            for (PricebookEntry pbe : [
                SELECT Id, Product2Id
                FROM PricebookEntry
                WHERE Id IN :pricebookEntryIds
            ]) {
                productByEntry.put(pbe.Id, pbe.Product2Id);
                productIds.add(pbe.Product2Id);
            }
        }

        // One query for all products.
        Map<Id, Product2> products = new Map<Id, Product2>([
            SELECT Id, Family FROM Product2 WHERE Id IN :productIds
        ]);

        for (OpportunityLineItem line : targets) {
            Id productId = line.Product2Id != null
                ? line.Product2Id
                : productByEntry.get(line.PricebookEntryId);
            Product2 product = productId == null ? null : products.get(productId);
            if (product != null) {
                line.Discount = PricingRules.standardDiscountForFamily(product.Family);
            }
        }
    }
}
