public with sharing class RenewalReminderService {

    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities = [
            SELECT Id, Name, CloseDate, OwnerId
            FROM Opportunity
            WHERE Id IN :opportunityIds
            AND Owner.IsActive = true
            WITH USER_MODE
        ];

        List<Messaging.SingleEmailMessage> messages = new List<Messaging.SingleEmailMessage>();

        for (Opportunity opp : opportunities) {
            Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();
            email.setTargetObjectId(opp.OwnerId);
            email.setSaveAsActivity(false);
            email.setSubject('Renewal due: ' + opp.Name);
            String closeDateText = opp.CloseDate == null ? 'not set' : opp.CloseDate.format();
            email.setPlainTextBody(
                'The opportunity "' + opp.Name + '" is due for renewal. ' +
                'Its close date is ' + closeDateText + '.'
            );
            messages.add(email);
        }

        if (messages.isEmpty()) {
            return 0;
        }

        // One sendEmail call for the whole batch: the limit is 10 calls per transaction.
        // allOrNothing=false so one failing email does not stop the others.
        List<Messaging.SendEmailResult> results = Messaging.sendEmail(messages, false);

        Integer sent = 0;
        for (Messaging.SendEmailResult result : results) {
            if (result.isSuccess()) {
                sent++;
            } else {
                for (Messaging.SendEmailError err : result.getErrors()) {
                    System.debug(LoggingLevel.WARN,
                        'Renewal reminder failed: ' + err.getStatusCode() + ' - ' + err.getMessage());
                }
            }
        }
        return sent;
    }
}
