        const requestId = ++this._requestId;
        this.isLoading = true;
        this.hasError = false;
        this.errorMessage = undefined;
        try {
            const result = await getOpenOpportunities({ accountId: this.recordId });
            if (requestId !== this._requestId) {
                return;
