```javascript
import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    stats;
    errorMessage;

    _intervalId;
    _isLoading = false;
    _connectionId = 0;
    _connected = false;

    _handleVisibilityChange = () => {
        if (!this._connected) {
            return;
        }
        if (document.visibilityState === 'hidden') {
            this.stopPolling();
        } else {
            this.startPolling();
        }
    };

    get hasStats() {
        return !!this.stats;
    }

    get waiting() {
        return this.stats ? this.stats.waiting : undefined;
    }

    get longestWaitMinutes() {
        return this.stats ? this.stats.longestWaitMinutes : undefined;
    }

    get hasError() {
        return !!this.errorMessage;
    }

    connectedCallback() {
        this._connected = true;
        this._connectionId += 1;
        this._isLoading = false;
        document.addEventListener(
            'visibilitychange',
            this._handleVisibilityChange
        );
        if (document.visibilityState !== 'hidden') {
            this.startPolling();
        }
    }

    disconnectedCallback() {
        this._connected = false;
        this._connectionId += 1; // invalidate any in-flight response
        this._isLoading = false;
        this.stopPolling();
        document.removeEventListener(
            'visibilitychange',
            this._handleVisibilityChange
        );
    }

    startPolling() {
        this.stopPolling();
        this.loadStats();
        // eslint-disable-next-line @lwc/lwc/no-async-operation
        this._intervalId = setInterval(() => {
            this.loadStats();
        }, REFRESH_INTERVAL_MS);
    }

    stopPolling() {
        if (this._intervalId !== undefined) {
            clearInterval(this._intervalId);
            this._intervalId = undefined;
        }
    }

    loadStats() {
        if (
            !this._connected ||
            this._isLoading ||
            document.visibilityState === 'hidden'
        ) {
            return;
        }
        this._isLoading = true;
        const connectionId = this._connectionId;
        getQueueStats()
            .then((result) => {
                if (connectionId !== this._connectionId) {
                    return;
                }
                this.stats = result;
                this.errorMessage = undefined;
            })
            .catch((error) => {
                if (connectionId !== this._connectionId) {
                    return;
                }
                this.errorMessage =
                    (error && error.body && error.body.message) ||
                    (error && error.message) ||
                    'Unknown error';
            })
            .finally(() => {
                if (connectionId === this._connectionId) {
                    this._isLoading = false;
                }
            });
    }
}
