```javascript
import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    _value;
    _activeValue;

    @api
    get options() {
        return this._options;
    }
    set options(v) {
        this._options = Array.isArray(v) ? v : [];
    }

    @api
    get value() {
        return this._value;
    }
    set value(v) {
        this._value = v;
        this._activeValue = v;
    }

    get hasValue() {
        return this._value !== undefined && this._value !== null && this._value !== '';
    }

    get activeIndex() {
        const opts = this._options;
        if (!opts.length) {
            return -1;
        }
        let idx = opts.findIndex((o) => o.value === this._activeValue);
        if (idx < 0 && this.hasValue) {
            idx = opts.findIndex((o) => o.value === this._value);
        }
        return idx < 0 ? 0 : idx;
    }

    get items() {
        const active = this.activeIndex;
        return this._options.map((o, i) => {
            const selected = this.hasValue && o.value === this._value;
            return {
                key: String(o.value),
                value: o.value,
                label: o.label,
                domId: 'opt-' + i,
                selected: selected ? 'true' : 'false',
                isActive: i === active
            };
        });
    }

    get activeDescendant() {
        const i = this.activeIndex;
        return i < 0 ? null : 'opt-' + i;
    }

    renderedCallback() {
        // Keep aria-activedescendant consistent with the (possibly rewritten) option id.
        const ul = this.template.querySelector('ul');
        if (!ul) {
            return;
        }
        const i = this.activeIndex;
        const lis = this.template.querySelectorAll('li');
        const li = i >= 0 ? lis[i] : null;
        if (li && li.id) {
            ul.setAttribute('aria-activedescendant', li.id);
        } else {
            ul.removeAttribute('aria-activedescendant');
        }
    }

    handleKeydown(event) {
        const opts = this._options;
        const last = opts.length - 1;
        const cur = this.activeIndex;
        let handled = true;
        switch (event.key) {
            case 'ArrowDown':
                this.setActive(Math.min(cur + 1, last));
                break;
            case 'ArrowUp':
                this.setActive(Math.max(cur - 1, 0));
                break;
            case 'Home':
                this.setActive(0);
                break;
            case 'End':
                this.setActive(last);
                break;
            case 'Enter':
            case ' ':
                if (cur >= 0) {
                    this.select(opts[cur].value);
                }
                break;
            default:
                handled = false;
        }
        if (handled) {
            event.preventDefault();
        }
    }

    setActive(index) {
        if (index >= 0 && index < this._options.length) {
            this._activeValue = this._options[index].value;
        }
    }

    handleClick(event) {
        const li = event.target.closest('li[role="option"]');
        if (!li) {
            return;
        }
        const idx = Array.from(this.template.querySelectorAll('li')).indexOf(li);
        if (idx < 0) {
            return;
        }
        this.select(this._options[idx].value);
    }

    select(value) {
        this._activeValue = value;
        if (this.hasValue && value === this._value) {
            return;
        }
        this._value = value;
        this.dispatchEvent(new CustomEvent('change', { detail: { value } }));
    }
}
