import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    _heading;
    items = [];
    newLabel = '';
    nextId = 1;

    @api
    get heading() {
        return this._heading;
    }
    set heading(value) {
        this._heading = value;
    }

    get displayHeading() {
        return this._heading ? String(this._heading).toUpperCase() : '';
    }

    @api
    get tasks() {
        return this.items;
    }
    set tasks(value) {
        this.items = Array.isArray(value) ? value.map((t) => ({ ...t })) : [];
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    generateId() {
        const used = new Set(this.items.map((t) => String(t.id)));
        let id;
        do {
            id = `new-${this.nextId++}`;
        } while (used.has(id));
        return id;
    }

    handleAdd() {
        const input = this.template.querySelector('lightning-input.new-task');
        const raw = input && input.value !== undefined && input.value !== null ? input.value : this.newLabel;
        const label = (raw || this.newLabel || '').trim();
        if (!label) {
            return;
        }
        this.items = [...this.items, { id: this.generateId(), label, done: false }];
        this.newLabel = '';
        if (input) {
            input.value = '';
        }
        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        const exists = this.items.some((t) => String(t.id) === id);
        if (!exists) {
            return;
        }
        this.items = this.items.map((t) =>
            String(t.id) === id ? { ...t, done: !t.done } : t
        );
    }
}
