```apex
public with sharing class EmployerService {

    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = new Set<Id>();
        for (Id contactId : employerByContactId.keySet()) {
            if (contactId != null && employerByContactId.get(contactId) != null) {
                contactIds.add(contactId);
            }
        }
        if (contactIds.isEmpty()) {
            return;
        }

        // Query 1: current primary affiliation lookup on the contacts
        Map<Id, Contact> contacts = new Map<Id, Contact>([
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :contactIds
            WITH USER_MODE
        ]);

        // Query 2: existing affiliations for these contacts
        Map<String, npe5__Affiliation__c> existingByKey = new Map<String, npe5__Affiliation__c>();
        for (npe5__Affiliation__c a : [
            SELECT Id, npe5__Contact__c, npe5__Organization__c, npe5__Status__c,
                   npe5__Primary__c, npe5__StartDate__c, npe5__EndDate__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :contactIds
            WITH USER_MODE
            ORDER BY CreatedDate DESC
        ]) {
            String key = String.valueOf(a.npe5__Contact__c) + '|' + String.valueOf(a.npe5__Organization__c);
            // keep the most recent / best candidate: prefer primary, else first (newest)
            npe5__Affiliation__c prev = existingByKey.get(key);
            if (prev == null || (a.npe5__Primary__c && !prev.npe5__Primary__c)) {
                existingByKey.put(key, a);
            }
        }

        List<npe5__Affiliation__c> toInsert = new List<npe5__Affiliation__c>();
        List<npe5__Affiliation__c> toUpdate = new List<npe5__Affiliation__c>();
        Date today = Date.today();

        for (Id contactId : contactIds) {
            Contact c = contacts.get(contactId);
            if (c == null) {
                continue;
            }
            Id orgId = employerByContactId.get(contactId);
            String key = String.valueOf(contactId) + '|' + String.valueOf(orgId);
            npe5__Affiliation__c existing = existingByKey.get(key);

            boolean alreadyPrimary = c.npsp__Primary_Affiliation__c == orgId
                && existing != null
                && existing.npe5__Primary__c
                && existing.npe5__Status__c == 'Current';
            if (alreadyPrimary) {
                continue;
            }

            if (existing != null) {
                existing.npe5__Status__c = 'Current';
                existing.npe5__Primary__c = true;
                existing.npe5__EndDate__c = null;
                if (existing.npe5__StartDate__c == null) {
                    existing.npe5__StartDate__c = today;
                }
                toUpdate.add(existing);
            } else {
                toInsert.add(new npe5__Affiliation__c(
                    npe5__Contact__c = contactId,
                    npe5__Organization__c = orgId,
                    npe5__Status__c = 'Current',
                    npe5__Primary__c = true,
                    npe5__StartDate__c = today
                ));
            }
        }

        // NPSP's affiliation trigger sets the contact's primary affiliation lookup
        // and converts any previous primary affiliation to Former with end date today.
        if (!toInsert.isEmpty()) {
            insert as user toInsert;
        }
        if (!toUpdate.isEmpty()) {
            update as user toUpdate;
        }
    }
}
