public with sharing class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    public class GiftImportException extends Exception {}

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // One staged record per gift, index aligned with input
        List<npsp__DataImport__c> staged = new List<npsp__DataImport__c>();
        for (WebGift g : gifts) {
            ImportResult r = new ImportResult();
            r.success = false;
            results.add(r);
            if (g == null) {
                staged.add(null);
                r.errorMessage = 'Gift is null.';
                continue;
            }
            staged.add(new npsp__DataImport__c(
                npsp__Contact1_Firstname__c = g.firstName,
                npsp__Contact1_Lastname__c = g.lastName,
                npsp__Contact1_Personal_Email__c = g.email,
                npsp__Donation_Amount__c = g.amount,
                npsp__Donation_Date__c = g.giftDate,
                npsp__Donation_Donor__c = 'Contact1'
            ));
        }

        List<npsp__DataImport__c> toInsert = new List<npsp__DataImport__c>();
        List<Integer> insertIdx = new List<Integer>();
        for (Integer i = 0; i < staged.size(); i++) {
            if (staged[i] != null) {
                toInsert.add(staged[i]);
                insertIdx.add(i);
            }
        }
        if (toInsert.isEmpty()) {
            return results;
        }

        List<Database.SaveResult> saveResults = Database.insert(toInsert, false);
        List<npsp__DataImport__c> toProcess = new List<npsp__DataImport__c>();
        List<Integer> processIdx = new List<Integer>();
        for (Integer j = 0; j < saveResults.size(); j++) {
            Integer idx = insertIdx[j];
            if (saveResults[j].isSuccess()) {
                toProcess.add(toInsert[j]);
                processIdx.add(idx);
            } else {
                String msg = '';
                for (Database.Error e : saveResults[j].getErrors()) {
                    msg += (msg == '' ? '' : '; ') + e.getMessage();
                }
                results[idx].errorMessage = 'Could not stage Data Import record: ' + msg;
            }
        }
        if (toProcess.isEmpty()) {
            return results;
        }

        try {
            npsp__Data_Import_Settings__c diSettings =
                npsp.BDI_DataImport_API.getDefaultDataImportSettings();
            npsp.BDI_DataImport_API.processDataImportRecords(diSettings, toProcess, false);
        } catch (Exception ex) {
            // Fall through: results are built from whatever NPSP wrote back
            for (Integer idx : processIdx) {
                results[idx].errorMessage = 'Data import processing error: ' + ex.getMessage();
            }
        }

        // Re-read the processed records to get NPSP's results
        Set<Id> ids = new Set<Id>();
        for (npsp__DataImport__c di : toProcess) {
            ids.add(di.Id);
        }
        Map<Id, npsp__DataImport__c> processed = new Map<Id, npsp__DataImport__c>([
            SELECT Id, npsp__Status__c, npsp__Contact1Imported__c,
                   npsp__DonationImported__c, npsp__FailureInformation__c
            FROM npsp__DataImport__c
            WHERE Id IN :ids
        ]);

        for (Integer k = 0; k < toProcess.size(); k++) {
            Integer idx = processIdx[k];
            npsp__DataImport__c di = processed.get(toProcess[k].Id);
            ImportResult r = results[idx];
            if (di == null) {
                if (r.errorMessage == null) {
                    r.errorMessage = 'Data Import record not found after processing.';
                }
                continue;
            }
            r.success = (di.npsp__Status__c == 'Imported');
            r.contactId = di.npsp__Contact1Imported__c;
            r.opportunityId = di.npsp__DonationImported__c;
            if (r.success) {
                r.errorMessage = null;
            } else {
                r.errorMessage = String.isNotBlank(di.npsp__FailureInformation__c)
                    ? di.npsp__FailureInformation__c
                    : (r.errorMessage != null ? r.errorMessage
                        : 'Import did not complete. Status: ' + di.npsp__Status__c);
            }
        }
        return results;
    }
}
