public with sharing class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    private static String key(Id oppId, Id conId) {
        return String.valueOf(oppId) + '|' + String.valueOf(conId);
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // ---- Collect ids and basic validation ----
        Set<Id> oppIds = new Set<Id>();
        Set<Id> conIds = new Set<Id>();
        for (SoftCreditRequest r : requests) {
            if (r == null || r.opportunityId == null || r.contactId == null) {
                throw new SoftCreditException('Each request needs an opportunityId and a contactId.');
            }
            oppIds.add(r.opportunityId);
            conIds.add(r.contactId);
        }

        // Query 1: opportunities
        Map<Id, Opportunity> opps = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :oppIds
        ]);

        for (SoftCreditRequest r : requests) {
            Opportunity opp = opps.get(r.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found or not accessible: ' + r.opportunityId);
            }
            if (opp.npsp__Primary_Contact__c != null && opp.npsp__Primary_Contact__c == r.contactId) {
                throw new SoftCreditException('Contact ' + r.contactId + ' is the primary contact of opportunity ' + opp.Id + '.');
            }
            if (r.amount == null || r.amount <= 0) {
                throw new SoftCreditException('Amount must be a positive number.');
            }
            if (opp.Amount == null || r.amount > opp.Amount) {
                throw new SoftCreditException('Amount cannot exceed the opportunity amount for ' + opp.Id + '.');
            }
        }

        // Query 2: existing contact roles
        Map<String, List<OpportunityContactRole>> rolesByKey = new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds AND ContactId IN :conIds
            ORDER BY CreatedDate, Id
        ]) {
            String k = key(ocr.OpportunityId, ocr.ContactId);
            if (!rolesByKey.containsKey(k)) {
                rolesByKey.put(k, new List<OpportunityContactRole>());
            }
            rolesByKey.get(k).add(ocr);
        }

        // Query 3: existing partial soft credits
        Map<String, List<npsp__Partial_Soft_Credit__c>> pscByKey = new Map<String, List<npsp__Partial_Soft_Credit__c>>();
        for (npsp__Partial_Soft_Credit__c psc : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c,
                   npsp__Role_Name__c, npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds AND npsp__Contact__c IN :conIds
            ORDER BY CreatedDate, Id
        ]) {
            String k = key(psc.npsp__Opportunity__c, psc.npsp__Contact__c);
            if (!pscByKey.containsKey(k)) {
                pscByKey.put(k, new List<npsp__Partial_Soft_Credit__c>());
            }
            pscByKey.get(k).add(psc);
        }

        // ---- Build contact role changes ----
        Map<String, OpportunityContactRole> keptRole = new Map<String, OpportunityContactRole>();
        List<OpportunityContactRole> ocrUpserts = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrDeletes = new List<OpportunityContactRole>();

        for (SoftCreditRequest r : requests) {
            String k = key(r.opportunityId, r.contactId);
            List<OpportunityContactRole> existing = rolesByKey.get(k);
            if (existing == null || existing.isEmpty()) {
                OpportunityContactRole n = new OpportunityContactRole(
                    OpportunityId = r.opportunityId,
                    ContactId = r.contactId,
                    Role = r.role
                );
                ocrUpserts.add(n);
                keptRole.put(k, n);
            } else {
                OpportunityContactRole keep = null;
                for (OpportunityContactRole o : existing) {
                    if (o.Role == r.role) { keep = o; break; }
                }
                if (keep == null) {
                    for (OpportunityContactRole o : existing) {
                        if (o.IsPrimary) { keep = o; break; }
                    }
                }
                if (keep == null) {
                    keep = existing[0];
                }
                for (OpportunityContactRole o : existing) {
                    if (o.Id != keep.Id) {
                        ocrDeletes.add(o);
                    }
                }
                if (keep.Role != r.role) {
                    ocrUpserts.add(new OpportunityContactRole(Id = keep.Id, Role = r.role));
                }
                keptRole.put(k, keep);
            }
        }

        // DML 1: upsert contact roles (insert new, update existing)
        if (!ocrUpserts.isEmpty()) {
            upsert ocrUpserts;
        }

        // ---- Build partial soft credit changes ----
        List<npsp__Partial_Soft_Credit__c> pscUpserts = new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> pscDeletes = new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest r : requests) {
            String k = key(r.opportunityId, r.contactId);
            String roleId = String.valueOf(keptRole.get(k).Id);
            List<npsp__Partial_Soft_Credit__c> existing = pscByKey.get(k);
            if (existing == null || existing.isEmpty()) {
                pscUpserts.add(new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = r.opportunityId,
                    npsp__Contact__c = r.contactId,
                    npsp__Amount__c = r.amount,
                    npsp__Role_Name__c = r.role,
                    npsp__Contact_Role_ID__c = roleId
                ));
            } else {
                pscUpserts.add(new npsp__Partial_Soft_Credit__c(
                    Id = existing[0].Id,
                    npsp__Amount__c = r.amount,
                    npsp__Role_Name__c = r.role,
                    npsp__Contact_Role_ID__c = roleId
                ));
                for (Integer i = 1; i < existing.size(); i++) {
                    pscDeletes.add(existing[i]);
                }
            }
        }

        // DML 2: delete duplicate soft credits (they may reference roles being removed)
        if (!pscDeletes.isEmpty()) {
            delete pscDeletes;
        }
        // DML 3: upsert soft credits
        if (!pscUpserts.isEmpty()) {
            upsert pscUpserts;
        }
        // DML 4: delete duplicate contact roles
        if (!ocrDeletes.isEmpty()) {
            delete ocrDeletes;
        }
    }
}
