public with sharing class GiftService {

    private static final String DONOR_ROLE = 'Donor';
    private static final String MEMBER_ROLE = 'Household Member';

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (contactId == null) {
            throw new IllegalArgumentException('Contact Id is required.');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be greater than zero.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('Gift date is required.');
        }

        List<Contact> contacts = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            WITH USER_MODE
            LIMIT 1
        ];
        if (contacts.isEmpty()) {
            throw new IllegalArgumentException('Contact not found: ' + contactId);
        }
        Contact donor = contacts[0];
        if (donor.AccountId == null) {
            throw new IllegalArgumentException('Contact has no household account.');
        }

        List<String> nameParts = new List<String>();
        if (String.isNotBlank(donor.FirstName)) {
            nameParts.add(donor.FirstName);
        }
        nameParts.add(donor.LastName);
        String oppName = String.join(nameParts, ' ') + ' Donation ' + String.valueOf(giftDate);

        Opportunity opp = new Opportunity(
            Name = oppName,
            AccountId = donor.AccountId,
            StageName = 'Closed Won',
            CloseDate = giftDate,
            Amount = amount,
            npsp__Primary_Contact__c = donor.Id
        );
        insert as user opp;

        reconcileContactRoles(opp.Id, donor);
        reconcilePayments(opp.Id, amount, giftDate);

        return opp.Id;
    }

    private static void reconcileContactRoles(Id oppId, Contact donor) {
        List<Contact> members = [
            SELECT Id
            FROM Contact
            WHERE AccountId = :donor.AccountId
            WITH USER_MODE
        ];
        Set<Id> memberIds = new Set<Id>();
        for (Contact c : members) {
            memberIds.add(c.Id);
        }
        memberIds.add(donor.Id);

        List<OpportunityContactRole> existing = [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :oppId
            WITH USER_MODE
            ORDER BY CreatedDate, Id
        ];

        Map<Id, OpportunityContactRole> keep = new Map<Id, OpportunityContactRole>();
        List<OpportunityContactRole> toDelete = new List<OpportunityContactRole>();
        for (OpportunityContactRole ocr : existing) {
            if (!memberIds.contains(ocr.ContactId)) {
                continue;
            }
            if (keep.containsKey(ocr.ContactId)) {
                toDelete.add(ocr);
            } else {
                keep.put(ocr.ContactId, ocr);
            }
        }

        List<OpportunityContactRole> toUpsert = new List<OpportunityContactRole>();
        for (Id cId : memberIds) {
            Boolean isDonor = (cId == donor.Id);
            String role = isDonor ? DONOR_ROLE : MEMBER_ROLE;
            OpportunityContactRole ocr = keep.get(cId);
            if (ocr == null) {
                toUpsert.add(new OpportunityContactRole(
                    OpportunityId = oppId,
                    ContactId = cId,
                    Role = role,
                    IsPrimary = isDonor
                ));
            } else if (ocr.Role != role || ocr.IsPrimary != isDonor) {
                ocr.Role = role;
                ocr.IsPrimary = isDonor;
                toUpsert.add(ocr);
            }
        }

        if (!toDelete.isEmpty()) {
            delete as user toDelete;
        }
        List<OpportunityContactRole> toUpdate = new List<OpportunityContactRole>();
        List<OpportunityContactRole> toInsert = new List<OpportunityContactRole>();
        for (OpportunityContactRole r : toUpsert) {
            if (r.Id == null) {
                toInsert.add(r);
            } else {
                toUpdate.add(r);
            }
        }
        // Clear primary flags first via updates, then insert new roles
        if (!toUpdate.isEmpty()) {
            update as user toUpdate;
        }
        if (!toInsert.isEmpty()) {
            insert as user toInsert;
        }
    }

    private static void reconcilePayments(Id oppId, Decimal amount, Date giftDate) {
        List<npe01__OppPayment__c> payments = [
            SELECT Id, npe01__Payment_Amount__c, npe01__Payment_Date__c,
                   npe01__Scheduled_Date__c, npe01__Paid__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :oppId
            WITH USER_MODE
            ORDER BY CreatedDate, Id
        ];

        if (payments.isEmpty()) {
            insert as user new npe01__OppPayment__c(
                npe01__Opportunity__c = oppId,
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            );
            return;
        }

        npe01__OppPayment__c first = payments[0];
        if (payments.size() > 1) {
            List<npe01__OppPayment__c> extras = new List<npe01__OppPayment__c>();
            for (Integer i = 1; i < payments.size(); i++) {
                extras.add(payments[i]);
            }
            delete as user extras;
        }

        if (first.npe01__Paid__c != true
            || first.npe01__Payment_Amount__c != amount
            || first.npe01__Payment_Date__c != giftDate) {
            first.npe01__Paid__c = true;
            first.npe01__Payment_Amount__c = amount;
            first.npe01__Payment_Date__c = giftDate;
            if (first.npe01__Scheduled_Date__c == null) {
                first.npe01__Scheduled_Date__c = giftDate;
            }
            update as user first;
        }
    }
}
