public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    // Opportunity Ids already audited in this transaction. Static state survives the
    // re-entrant trigger run caused by TA_Opportunity_RoundAmount's second update, so the
    // rounding does not produce a second task for the same opportunity.
    @TestVisible
    private static Set<Id> loggedOpportunityIds = new Set<Id>();

    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        Map<Id, Opportunity> oldMap = new Map<Id, Opportunity>(triggerOld);
        List<Task> tasks = new List<Task>();

        for (Opportunity opp : triggerNew) {
            Opportunity oldOpp = oldMap.get(opp.Id);
            if (oldOpp == null || loggedOpportunityIds.contains(opp.Id)) {
                continue;
            }
            if (opp.Amount != oldOpp.Amount) {
                loggedOpportunityIds.add(opp.Id);
                tasks.add(
                    new Task(
                        Subject = 'Amount changed',
                        WhatId = opp.Id,
                        Status = 'Completed'
                    )
                );
            }
        }

        if (!tasks.isEmpty()) {
            insert tasks;
        }
    }
}
