public inherited sharing class TA_Contact_DefaultLeadSource implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accounts = TA_Contact_Queries.getInstance().accountsById;
        for (Contact c : (List<Contact>) triggerNew) {
            if (c.AccountId == null || !String.isBlank(c.LeadSource)) {
                continue;
            }
            Account acc = accounts.get(c.AccountId);
            if (acc != null) {
                c.LeadSource = acc.AccountSource;
            }
        }
    }
}
